271	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
272	  const index = state[key];
273	  if (index === null) return;
274	
275	  commitEntry(session, index);
276	  state[key] = null;
277	
278	  // Only what the client received can be retracted, and only assistant entries.
279	  if (state.suppressOutput) return;
280	
281	  sendCommit(ws, index);
282	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
283	}
