295	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
296	  for (const msg of clientMessages) {
297	    log.debug('stream', 'forwarding client message to frontend', {
298	      type: msg.type,
299	      index: 'index' in msg ? msg.index : undefined,
300	    });
301	    sendJson(ws, msg);
302	  }
303	}
