305	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
306	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
307	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
308	  commitOpenEntries(ws, session, state);
309	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
310	
311	  for (const idx of state.sentAssistantIndices) {
312	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
313	    markSuppressed(session, idx);
314	  }
315	
316	  state.sentAssistantIndices = [];
317	  state.suppressOutput = true;
318	}
