325	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
326	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
327	  for (const segment of parser.flush()) {
328	    handleTextSegment(ws, session, state, segment);
329	  }
330	}
