332	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
333	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
334	  const index = state[key];
335	  if (index === null) return;
336	  markTruncated(session, index);
337	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
338	  commitAndClear(ws, session, state, key);
339	}
