346	async function handleListSessions(
347	  ws: WebSocket,
348	  session: ChatSession,
349	  sessionStore: SessionStore | undefined,
350	  message: ListSessionsMessage
351	): Promise<void> {
352	  if (!sessionStore?.listFor) {
353	    sendJson(ws, {type: 'session_list', sessions: []});
354	    return;
355	  }
356	
357	  try {
358	    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
359	    const sessions = summaries.map(s => ({
360	      sessionId: s.sessionId,
361	      createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : s.createdAt,
362	      updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : s.updatedAt,
363	      entryCount: s.entryCount,
364	    }));
365	    sendJson(ws, {type: 'session_list', sessions});
366	  } catch (error) {
367	    const message = error instanceof Error ? error.message : 'Unknown error';
368	    log.error('ws', 'list_sessions failed', {userId: session.userId, error: message});
369	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to retrieve conversation list');
370	  }
371	}
